import { Hono } from "https://deno.land/x/hono@v3.4.1/mod.ts";
import { cors } from "https://deno.land/x/hono@v3.4.1/middleware.ts";
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { Client } from "https://deno.land/x/postgres@v0.17.0/mod.ts";

import auth from "./auth.ts";
import categories from "./categories.ts";
import profile from "./profile.ts";
import bookings from "./bookings.ts";
import payments from "./payments.ts";
import settings from "./settings.ts";
import chat from "./chat.ts";
import faqs from "./faqs.ts";
import admin from "./admin.ts";
import labourers from "./labourers.ts";

const app = new Hono();

// Enable CORS
app.use("/*", cors());

// Health Check
app.get("/", (c) => c.text("WILL backend running on Supabase Edge Functions ✅"));
app.get("/api", (c) => c.text("WILL API Gateway running ✅"));

// Register Routes
app.route("/api/auth", auth);
app.route("/api/categories", categories);
app.route("/api/profile", profile);
app.route("/api/bookings", bookings);
app.route("/api/payments", payments);
app.route("/api/settings", settings);
app.route("/api/chat", chat);
app.route("/api/faqs", faqs);
app.route("/api/admin", admin);
app.route("/api/labourers", labourers);

// WebSocket Connections Map (bookingId -> Set of WebSockets)
const activeConnections = new Map<string, Set<WebSocket>>();

function addSocketConnection(bookingId: string, ws: WebSocket) {
  if (!activeConnections.has(bookingId)) {
    activeConnections.set(bookingId, new Set());
  }
  activeConnections.get(bookingId)!.add(ws);
  console.log(`[WS] Connected to room: booking_${bookingId}. Active sockets: ${activeConnections.get(bookingId)!.size}`);
}

function removeSocketConnection(bookingId: string, ws: WebSocket) {
  const room = activeConnections.get(bookingId);
  if (room) {
    room.delete(ws);
    console.log(`[WS] Disconnected from room: booking_${bookingId}. Active sockets: ${room.size}`);
    if (room.size === 0) {
      activeConnections.delete(bookingId);
    }
  }
}

// Socket.io Compatibility upgrade route (since mobile app is already published)
app.get("/api/socket.io", async (c) => {
  const transport = c.req.query("transport");

  if (transport === "websocket") {
    if (c.req.header("upgrade") !== "websocket") {
      return c.text("Not a WebSocket request", 400);
    }

    const rawReq = (c.req.raw as any).originalRequest || c.req.raw;
    const { socket, response } = Deno.upgradeWebSocket(rawReq);

    let currentBookingId: string | null = null;

    socket.onopen = () => {
      // Send Socket.io connection confirmation packet (40)
      socket.send("40");
      console.log("[Socket.ioCompat] Client connected via WebSocket");
    };

    socket.onmessage = (event) => {
      const msg = event.data.toString();

      if (msg === "2probe") {
        // Engine.io Probe Ping -> Respond with Probe Pong (3probe)
        socket.send("3probe");
      } else if (msg === "5") {
        // Engine.io Upgrade confirm -> Send Socket.io connect frame
        socket.send("40");
      } else if (msg === "2") {
        // Engine.io Ping -> Respond with Pong (3)
        socket.send("3");
      } else if (msg.startsWith("42")) {
        try {
          const payload = JSON.parse(msg.substring(2));
          if (Array.isArray(payload)) {
            const [eventName, bookingId] = payload;
            if (eventName === "join_booking" && bookingId) {
              currentBookingId = bookingId;
              addSocketConnection(bookingId, socket);
            } else if (eventName === "leave_booking" && bookingId) {
              removeSocketConnection(bookingId, socket);
              currentBookingId = null;
            }
          }
        } catch (e: any) {
          console.error("[Socket.ioCompat] Error parsing event:", e.message);
        }
      }
    };

    const socketClosedPromise = new Promise<void>((resolve) => {
      socket.onclose = () => {
        if (currentBookingId) {
          removeSocketConnection(currentBookingId, socket);
        }
        console.log("[Socket.ioCompat] Client disconnected");
        resolve();
      };
    });

    if (typeof (globalThis as any).EdgeRuntime !== "undefined") {
      (globalThis as any).EdgeRuntime.waitUntil(socketClosedPromise);
    }

    socket.onerror = (e) => {
      console.error("[Socket.ioCompat] Socket error:", e);
    };

    return response;
  } else if (transport === "polling") {
    // Engine.io Handshake for polling
    const sid = Math.random().toString(36).substring(2, 15);
    const handshake = {
      sid,
      upgrades: ["websocket"],
      pingInterval: 25000,
      pingTimeout: 20000
    };
    c.header("Content-Type", "text/plain; charset=UTF-8");
    return c.text("0" + JSON.stringify(handshake));
  }

  return c.text("Bad Request", 400);
});

// Also support POST for polling connection fallback
app.post("/api/socket.io", (c) => {
  c.header("Content-Type", "text/plain; charset=UTF-8");
  return c.text("ok");
});

// Background Listener for PostgreSQL NOTIFY notifications
async function startPostgresListener() {
  const databaseUrl = Deno.env.get("SUPABASE_DB_URL") || Deno.env.get("DATABASE_URL") || "";
  if (!databaseUrl) {
    console.warn("WARNING: SUPABASE_DB_URL not set. WebSocket real-time updates will NOT be active.");
    return;
  }

  const client = new Client(databaseUrl);

  try {
    await client.connect();
    await client.queryObject("LISTEN booking_updates");
    console.log("[WS Listener] Subscribed to Postgres LISTEN 'booking_updates' channel.");

    for await (const notification of client.notifications) {
      try {
        const payload = JSON.parse(notification.payload);
        const { bookingId, event, data } = payload;

        const room = activeConnections.get(bookingId);
        if (room && room.size > 0) {
          console.log(`[WS Listener] Broadcasting event '${event}' to ${room.size} clients for booking ${bookingId}`);

          // Format as Socket.io packet: "42" + json_array([event, data])
          const messageStr = "42" + JSON.stringify([event, data]);

          for (const ws of room) {
            if (ws.readyState === WebSocket.OPEN) {
              ws.send(messageStr);
            }
          }
        }
      } catch (err: any) {
        console.error("[WS Listener] Error parsing payload:", err.message);
      }
    }
  } catch (err: any) {
    console.error("[WS Listener] Postgres listener connection lost. Retrying in 5 seconds...", err.message);
    setTimeout(startPostgresListener, 5000);
  }
}

// Run Postgres listener in background
startPostgresListener();

// WebSocket Upgrade Handler using native Deno Request
function handleWebSocket(req: Request): Response {
  const url = new URL(req.url);
  const transport = url.searchParams.get("transport");

  if (transport !== "websocket") {
    return new Response("Bad Request", { status: 400 });
  }

  const { socket, response } = Deno.upgradeWebSocket(req);

  let currentBookingId: string | null = null;

  socket.onopen = () => {
    // Send Socket.io connection confirmation packet (40)
    socket.send("40");
    console.log("[Socket.ioCompat] Client connected via WebSocket");
  };

  socket.onmessage = (event) => {
    const msg = event.data.toString();

    if (msg === "2probe") {
      // Engine.io Probe Ping -> Respond with Probe Pong (3probe)
      socket.send("3probe");
    } else if (msg === "5") {
      // Engine.io Upgrade confirm -> Send Socket.io connect frame
      socket.send("40");
    } else if (msg === "2") {
      // Engine.io Ping -> Respond with Pong (3)
      socket.send("3");
    } else if (msg.startsWith("42")) {
      try {
        const payload = JSON.parse(msg.substring(2));
        if (Array.isArray(payload)) {
          const [eventName, bookingId] = payload;
          if (eventName === "join_booking" && bookingId) {
            currentBookingId = bookingId;
            addSocketConnection(bookingId, socket);
          } else if (eventName === "leave_booking" && bookingId) {
            removeSocketConnection(bookingId, socket);
            currentBookingId = null;
          }
        }
      } catch (e: any) {
        console.error("[Socket.ioCompat] Error parsing event:", e.message);
      }
    }
  };

  const socketClosedPromise = new Promise<void>((resolve) => {
    socket.onclose = () => {
      if (currentBookingId) {
        removeSocketConnection(currentBookingId, socket);
      }
      console.log("[Socket.ioCompat] Client disconnected");
      resolve();
    };
  });

  if (typeof (globalThis as any).EdgeRuntime !== "undefined") {
    (globalThis as any).EdgeRuntime.waitUntil(socketClosedPromise);
  }

  socket.onerror = (e) => {
    console.error("[Socket.ioCompat] Socket error:", e);
  };

  return response;
}

// Serve the Hono application with a URL path rewriting wrapper
serve((req) => {
  const url = new URL(req.url);

  // Normalize path
  let normalizedPath = url.pathname;
  if (normalizedPath.startsWith("/functions/v1/api/")) {
    normalizedPath = "/api/" + normalizedPath.substring(18);
  } else if (normalizedPath === "/functions/v1/api") {
    normalizedPath = "/api";
  }

  // Handle double /api/api prefix if custom domain mapping proxies the path
  if (normalizedPath.startsWith("/api/api/")) {
    normalizedPath = "/api/" + normalizedPath.substring(9);
  } else if (normalizedPath === "/api/api") {
    normalizedPath = "/api";
  }

  // Strip trailing slash to handle trailing slash routing differences (e.g. /api/socket.io/)
  if (normalizedPath !== "/" && normalizedPath.endsWith("/")) {
    normalizedPath = normalizedPath.substring(0, normalizedPath.length - 1);
  }

  // Intercept WebSocket upgrade requests for /api/socket.io
  const upgrade = req.headers.get("upgrade") || "";
  if (upgrade.toLowerCase() === "websocket" && normalizedPath === "/api/socket.io") {
    return handleWebSocket(req);
  }

  url.pathname = normalizedPath;
  const newReq = new Request(url.toString(), req);
  Object.defineProperty(newReq, "originalRequest", {
    value: req,
    enumerable: false,
    writable: true,
    configurable: true
  });
  return app.fetch(newReq);
});

import { Hono } from "https://deno.land/x/hono@v3.4.1/mod.ts";
import jwt from "npm:jsonwebtoken@^9.0.0";
import bcrypt from "npm:bcryptjs@^3.0.0";
import admin from "npm:firebase-admin@^13.6.0";
import { query, queryOne, generateId } from "./db.ts";

const JWT_SECRET = Deno.env.get("JWT_SECRET") || "secret";

const auth = new Hono();

// JWT verification middleware
export async function verifyToken(c: any, next: any) {
  const token = c.req.header("x-auth-token");
  if (!token) {
    return c.json({ msg: "No token, authorization denied" }, 401);
  }

  try {
    const decoded = jwt.verify(token, JWT_SECRET) as any;
    c.set("user", decoded.user);
    await next();
  } catch (err) {
    return c.json({ msg: "Token is not valid" }, 401);
  }
}

// Helper: Sign JWT
function signToken(userId: string): string {
  return jwt.sign({ user: { id: userId } }, JWT_SECRET, { expiresIn: "30d" });
}

// Helper: Verify Google Token via HTTP API
async function verifyGoogleToken(idToken: string) {
  const response = await fetch(`https://oauth2.googleapis.com/tokeninfo?id_token=${idToken}`);
  if (!response.ok) {
    throw new Error("Failed to verify Google token");
  }
  const payload = await response.json();
  if (payload.error_description) {
    throw new Error(payload.error_description);
  }
  return {
    email: payload.email,
    name: payload.name || payload.email.split("@")[0],
    picture: payload.picture || ""
  };
}

// POST /api/auth/google
auth.post("/google", async (c) => {
  const { idToken, role, action, phoneNumber } = await c.req.json();

  if (!idToken) {
    return c.json({ msg: "No token provided" }, 400);
  }

  try {
    const { email, name, picture } = await verifyGoogleToken(idToken);

    let user = await queryOne(
      "SELECT * FROM users WHERE email = $1 AND role = $2",
      [email, role || "user"]
    );

    if (!user) {
      // Create user account
      const randomDummyPassword = await bcrypt.hash(Math.random().toString(36).slice(-10), 10);
      const userId = generateId();
      const referralCode = 'WILL' + userId.substring(18).toUpperCase();

      user = await queryOne(
        `INSERT INTO users (id, name, email, password, role, profile_picture, referral_code) 
         VALUES ($1, $2, $3, $4, $5, $6, $7) 
         RETURNING *`,
        [userId, name, email, randomDummyPassword, role || "user", picture, referralCode]
      );

      if (user && user.role === "worker") {
        const workerId = generateId();
        await query(
          `INSERT INTO labourers (id, user_id, name, category, hourly_rate, location, experience_years, image_url) 
           VALUES ($1, $2, $3, $4, $5, $6, $7, $8)`,
          [workerId, user.id, user.name, "General", 0, "Not set", 0, picture]
        );
      }
    }

    if (!user) {
      return c.json({ msg: "Failed to create user" }, 500);
    }

    // Direct phone direct check
    if (role === "worker" && !user.phoneNumber && !phoneNumber) {
      return c.json({
        msg: "Phone number is mandatory for worker accounts.",
        code: "PHONE_REQUIRED",
        user: { id: user.id, email: user.email, name: user.name }
      }, 400);
    }

    if (phoneNumber && !user.phoneNumber) {
      await query("UPDATE users SET phone_number = $1 WHERE id = $2", [phoneNumber, user.id]);
      user.phoneNumber = phoneNumber;
    }

    const token = signToken(user.id);
    return c.json({ 
      token, 
      role: user.role, 
      name: user.name, 
      profilePicture: user.profilePicture || "" 
    });

  } catch (err: any) {
    console.error("Google Auth Error:", err);
    return c.json({ msg: "Google Authentication failed", detail: err.message }, 401);
  }
});

// POST /api/auth/signup
auth.post("/signup", async (c) => {
  const { name, email, password, role, profilePicture } = await c.req.json();

  try {
    const existing = await queryOne(
      "SELECT id FROM users WHERE email = $1 AND role = $2",
      [email, role || "user"]
    );
    if (existing) {
      return c.json({ msg: "User already exists" }, 400);
    }

    const salt = await bcrypt.genSalt(10);
    const hashedPassword = await bcrypt.hash(password, salt);
    const userId = generateId();
    const referralCode = 'WILL' + userId.substring(18).toUpperCase();

    const user = await queryOne(
      `INSERT INTO users (id, name, email, password, role, profile_picture, referral_code) 
       VALUES ($1, $2, $3, $4, $5, $6, $7) 
       RETURNING *`,
      [userId, name, email, hashedPassword, role || "user", profilePicture || "", referralCode]
    );

    if (!user) {
      return c.json({ msg: "Server Error" }, 500);
    }

    if (role === "worker") {
      const workerId = generateId();
      await query(
        `INSERT INTO labourers (id, user_id, name, category, hourly_rate, location, experience_years, image_url) 
         VALUES ($1, $2, $3, $4, $5, $6, $7, $8)`,
        [workerId, user.id, user.name, "General", 0, "Not set", 0, profilePicture || ""]
      );
    }

    const token = signToken(user.id);
    return c.json({ 
      token, 
      role: user.role, 
      name: user.name, 
      profilePicture: user.profilePicture || "" 
    });

  } catch (err: any) {
    console.error("Signup Error:", err.message);
    return c.json({ msg: "Server Error" }, 500);
  }
});

// POST /api/auth/login
auth.post("/login", async (c) => {
  const { email, password, role } = await c.req.json();

  try {
    if (!role) {
      return c.json({ msg: "Role is required" }, 400);
    }

    const user = await queryOne(
      "SELECT * FROM users WHERE email = $1 AND role = $2",
      [email, role]
    );
    if (!user) {
      return c.json({ msg: "Invalid Credentials" }, 400);
    }

    const isMatch = await bcrypt.compare(password, user.password || "");
    if (!isMatch) {
      return c.json({ msg: "Invalid Credentials" }, 400);
    }

    const token = signToken(user.id);
    return c.json({ 
      token, 
      role: user.role, 
      name: user.name, 
      profilePicture: user.profilePicture || "" 
    });

  } catch (err: any) {
    console.error("Login Error:", err.message);
    return c.json({ msg: "Server Error" }, 500);
  }
});

// POST /api/auth/phone-login
auth.post("/phone-login", async (c) => {
  const { idToken, role } = await c.req.json();

  try {
    if (!idToken) {
      return c.json({ msg: "No token provided" }, 400);
    }

    // Verify via Firebase Admin SDK
    const decodedToken = await admin.auth().verifyIdToken(idToken);
    const phoneNumber = decodedToken.phone_number;

    if (!phoneNumber) {
      return c.json({ msg: "Invalid token: No phone number found" }, 400);
    }

    let user = await queryOne(
      "SELECT * FROM users WHERE phone_number = $1 AND role = $2",
      [phoneNumber, role || "user"]
    );

    if (!user) {
      // Create user
      const userId = generateId();
      const referralCode = 'WILL' + userId.substring(18).toUpperCase();
      const defaultName = "User " + phoneNumber.slice(-4);

      user = await queryOne(
        `INSERT INTO users (id, name, phone_number, role, referral_code) 
         VALUES ($1, $2, $3, $4, $5) 
         RETURNING *`,
        [userId, defaultName, phoneNumber, role || "user", referralCode]
      );

      if (user && user.role === "worker") {
        const workerId = generateId();
        await query(
          `INSERT INTO labourers (id, user_id, name, category, hourly_rate, location, experience_years) 
           VALUES ($1, $2, $3, $4, $5, $6, $7)`,
          [workerId, user.id, user.name, "General", 0, "Not set", 0]
        );
      }
    }

    if (!user) {
      return c.json({ msg: "Failed to authenticate" }, 500);
    }

    const token = signToken(user.id);
    return c.json({ 
      token, 
      role: user.role, 
      name: user.name, 
      profilePicture: user.profilePicture || "" 
    });

  } catch (err: any) {
    console.error("Phone Login Error:", err.message);
    return c.json({ msg: "Phone Authentication failed" }, 401);
  }
});

// PUT /api/auth/phone
auth.put("/phone", verifyToken, async (c) => {
  const { idToken } = await c.req.json();
  const userId = c.get("user").id;

  try {
    if (!idToken) {
      return c.json({ msg: "No verification token provided" }, 400);
    }

    const decodedToken = await admin.auth().verifyIdToken(idToken);
    const newPhoneNumber = decodedToken.phone_number;

    if (!newPhoneNumber) {
      return c.json({ msg: "Invalid token: No phone number found" }, 400);
    }

    const user = await queryOne("SELECT * FROM users WHERE id = $1", [userId]);
    if (!user) {
      return c.json({ msg: "User not found" }, 404);
    }

    // Check if duplicate exists for the same role
    const duplicate = await queryOne(
      "SELECT id FROM users WHERE phone_number = $1 AND role = $2 AND id != $3",
      [newPhoneNumber, user.role, user.id]
    );

    if (duplicate) {
      return c.json({ msg: "This phone number is already registered with another account." }, 400);
    }

    await query("UPDATE users SET phone_number = $1 WHERE id = $2", [newPhoneNumber, user.id]);

    return c.json({ msg: "Phone number updated successfully", phoneNumber: newPhoneNumber });

  } catch (err: any) {
    console.error("Phone Update Error:", err.message);
    return c.json({ msg: "Failed to update phone number" }, 500);
  }
});

// PUT /api/auth/phone-direct
auth.put("/phone-direct", verifyToken, async (c) => {
  const { phoneNumber } = await c.req.json();
  const userId = c.get("user").id;

  try {
    if (!phoneNumber) {
      return c.json({ msg: "Phone number is required" }, 400);
    }

    if (phoneNumber.length < 10) {
      return c.json({ msg: "Invalid phone number" }, 400);
    }

    const user = await queryOne("SELECT * FROM users WHERE id = $1", [userId]);
    if (!user) {
      return c.json({ msg: "User not found" }, 404);
    }

    const duplicate = await queryOne(
      "SELECT id FROM users WHERE phone_number = $1 AND role = $2 AND id != $3",
      [phoneNumber, user.role, user.id]
    );

    if (duplicate) {
      return c.json({ msg: "This phone number is already registered with another account." }, 400);
    }

    await query("UPDATE users SET phone_number = $1 WHERE id = $2", [phoneNumber, user.id]);

    return c.json({ msg: "Phone number updated successfully", phoneNumber });

  } catch (err: any) {
    console.error("Phone Update Direct Error:", err.message);
    return c.json({ msg: "Failed to update phone number" }, 500);
  }
});

// GET /api/auth/check-other-role
auth.get("/check-other-role", verifyToken, async (c) => {
  const userId = c.get("user").id;

  try {
    const currentUser = await queryOne("SELECT * FROM users WHERE id = $1", [userId]);
    if (!currentUser) {
      return c.json({ msg: "User not found" }, 404);
    }

    const otherRole = currentUser.role === "worker" ? "user" : "worker";
    let otherUser = null;

    if (currentUser.email) {
      otherUser = await queryOne(
        "SELECT * FROM users WHERE email = $1 AND role = $2",
        [currentUser.email, otherRole]
      );
    }

    if (!otherUser && currentUser.phoneNumber) {
      otherUser = await queryOne(
        "SELECT * FROM users WHERE phone_number = $1 AND role = $2",
        [currentUser.phoneNumber, otherRole]
      );
    }

    return c.json({
      hasOtherAccount: !!otherUser,
      otherRole,
      otherUser: otherUser ? {
        id: otherUser.id,
        name: otherUser.name,
        role: otherUser.role
      } : null
    });

  } catch (err: any) {
    console.error("check-other-role error:", err.message);
    return c.json({ msg: "Server error" }, 500);
  }
});

export default auth;

import { Pool } from "https://deno.land/x/postgres@v0.17.0/mod.ts";

const databaseUrl = Deno.env.get("SUPABASE_DB_URL") || Deno.env.get("DATABASE_URL") || "";
const pool = new Pool(databaseUrl, 5, true);

// Utility: Generate a 24-character hex ID (similar to MongoDB ObjectId)
export function generateId(): string {
  const timestamp = Math.floor(Date.now() / 1000).toString(16).padStart(8, '0');
  const random = Array.from({ length: 16 }, () => 
    Math.floor(Math.random() * 16).toString(16)
  ).join('');
  return (timestamp + random).substring(0, 24);
}

// Utility: Convert snake_case object keys to camelCase
export function toCamel(obj: any): any {
  if (Array.isArray(obj)) {
    return obj.map(v => toCamel(v));
  } else if (obj instanceof Date) {
    return obj;
  } else if (obj !== null && typeof obj === 'object') {
    return Object.keys(obj).reduce((result, key) => {
      const camelKey = key.replace(/_([a-z])/g, (_, letter) => letter.toUpperCase());
      result[camelKey] = toCamel(obj[key]);
      return result;
    }, {} as any);
  }
  return obj;
}

// Utility: Convert camelCase object keys to snake_case
export function toSnake(obj: any): any {
  if (Array.isArray(obj)) {
    return obj.map(v => toSnake(v));
  } else if (obj instanceof Date) {
    return obj;
  } else if (obj !== null && typeof obj === 'object') {
    return Object.keys(obj).reduce((result, key) => {
      const snakeKey = key.replace(/[A-Z]/g, letter => `_${letter.toLowerCase()}`);
      result[snakeKey] = toSnake(obj[key]);
      return result;
    }, {} as any);
  }
  return obj;
}

// Run a database query and return camelCase objects
export async function query<T = any>(sql: string, params?: any[]): Promise<T[]> {
  const client = await pool.connect();
  try {
    const result = await client.queryObject<any>(sql, params);
    return toCamel(result.rows);
  } finally {
    client.release();
  }
}

// Run a query that returns a single row or null
export async function queryOne<T = any>(sql: string, params?: any[]): Promise<T | null> {
  const rows = await query<T>(sql, params);
  return rows.length > 0 ? rows[0] : null;
}

import { Hono } from "https://deno.land/x/hono@v3.4.1/mod.ts";
import { query } from "./db.ts";

