// POST /api/profile/referral/apply
profile.post("/referral/apply", verifyToken, async (c) => {
  const userId = c.get("user").id;
  const { code } = await c.req.json();

  if (!code) {
    return c.json({ success: false, message: "Referral code is required" }, 400);
  }

  try {
    const currentUser = await queryOne("SELECT * FROM users WHERE id = $1", [userId]);
    if (!currentUser) {
      return c.json({ success: false, message: "User not found" }, 404);
    }

    if (currentUser.referredBy) {
      return c.json({ success: false, message: "You have already applied a referral code" }, 400);
    }

    // Find referrer (case-insensitive check)
    const referrer = await queryOne(
      "SELECT * FROM users WHERE LOWER(referral_code) = LOWER($1)",
      [code.trim()]
    );

    if (!referrer) {
      return c.json({ success: false, message: "Invalid referral code" }, 400);
    }

    if (referrer.id === currentUser.id) {
      return c.json({ success: false, message: "You cannot use your own referral code" }, 400);
    }

    const currentNewBalance = Number(currentUser.walletBalance || 0) + 100;
    const referrerNewBalance = Number(referrer.walletBalance || 0) + 100;

    // Apply referrals update
    await query(
      "UPDATE users SET referred_by = $1, wallet_balance = $2 WHERE id = $3",
      [referrer.id, currentNewBalance, currentUser.id]
    );
    await query(
      "UPDATE users SET wallet_balance = $1 WHERE id = $2",
      [referrerNewBalance, referrer.id]
    );

    // Record wallet transactions
    const tx1 = generateId();
    const tx2 = generateId();

    await query(
      `INSERT INTO wallet_transactions (id, user_id, amount, type, description, date) 
       VALUES ($1, $2, 100, 'credit', $3, NOW())`,
      [tx1, currentUser.id, `Referral bonus (Code applied: ${referrer.referralCode})`]
    );

    await query(
      `INSERT INTO wallet_transactions (id, user_id, amount, type, description, date) 
       VALUES ($1, $2, 100, 'credit', $3, NOW())`,
      [tx2, referrer.id, `Referral reward (Referred user: ${currentUser.name})`]
    );

    return c.json({
      success: true,
      message: "Referral applied successfully!",
      walletBalance: currentNewBalance
    });

  } catch (err: any) {
    console.error("Apply Referral Error:", err.message);
    return c.json({ success: false, message: "Server error" }, 500);
  }
});

