// GET /api/bookings/worker
bookings.get("/worker", verifyToken, async (c) => {
  const userId = c.get("user").id;
  try {
    const labourer = await queryOne("SELECT * FROM labourers WHERE user_id = $1", [userId]);
    if (!labourer) {
      return c.json({ msg: "Labourer profile not found" }, 404);
    }

    const expirationTime = new Date(Date.now() - 3 * 60 * 60 * 1000).toISOString();

    let list;
    if (labourer.isOnline !== false) {
      list = await query(
        `SELECT * FROM bookings 
         WHERE labourer_id = $1 
            OR (labourer_id IS NULL 
                AND category = $2 
                AND status = 'pending' 
                AND payment_status = 'paid'
                AND date > $3
                AND id NOT IN (SELECT booking_id FROM booking_declined_by WHERE labourer_id = $1)
               )
         ORDER BY date DESC`,
        [labourer.id, labourer.category, expirationTime]
      );
    } else {
      list = await query(
        `SELECT * FROM bookings WHERE labourer_id = $1 ORDER BY date DESC`,
        [labourer.id]
      );
    }

    const activeCommitments = await query(
      `SELECT * FROM bookings 
       WHERE labourer_id = $1 
         AND status IN ('confirmed', 'arrived') 
         AND payment_status = 'paid'`,
      [labourer.id]
    );

    const filtered = [];
    for (const b of list) {
      if (b.labourerId === labourer.id) {
        filtered.push(b);
        continue;
      }

      // Check applicants list
      const isApp = await queryOne("SELECT 1 FROM booking_applicants WHERE booking_id = $1 AND labourer_id = $2", [b.id, labourer.id]);
      if (isApp) {
        filtered.push(b);
        continue;
      }

      // Check overlap
      const bStart = new Date(b.date).getTime();
      const bEnd = bStart + (Number(b.numberOfHours) || 2) * 60 * 60 * 1000;
      let overlap = false;

      for (const active of activeCommitments) {
        if (active.id === b.id) continue;
        const aStart = new Date(active.date).getTime();
        const aEnd = aStart + (Number(active.numberOfHours) || 2) * 60 * 60 * 1000;
        if (bStart < aEnd && bEnd > aStart) {
          overlap = true;
          break;
        }
      }

      if (!overlap) {
        filtered.push(b);
      }
    }

    const populated = await Promise.all(filtered.map((b: any) => populateBooking(b)));
    return c.json(populated);

  } catch (err: any) {
    console.error("GET /worker bookings error:", err.message);
    return c.json({ msg: "Server Error" }, 500);
  }
});

// GET /api/bookings/:id
bookings.get("/:id", verifyToken, async (c) => {
  const userId = c.get("user").id;
  const bookingId = c.req.param("id");

  try {
    const rawBooking = await queryOne("SELECT * FROM bookings WHERE id = $1", [bookingId]);
    if (!rawBooking) return c.json({ msg: "Booking not found" }, 404);

    const booking = await populateBooking(rawBooking);

    const isOwner = booking.user?.id === userId;
    const labourer = await queryOne("SELECT id, category FROM labourers WHERE user_id = $1", [userId]);

    let isApplicant = false;
    if (labourer) {
      const applicant = await queryOne("SELECT 1 FROM booking_applicants WHERE booking_id = $1 AND labourer_id = $2", [bookingId, labourer.id]);
      isApplicant = !!applicant;
    }

    const bookingLabourerId = booking.labourer?.id || null;
    const isLabourer = labourer && (
      (bookingLabourerId && bookingLabourerId === labourer.id) ||
      isApplicant ||
      (!bookingLabourerId && booking.status === "pending" && booking.paymentStatus === "paid" && booking.category === labourer.category)
    );

    if (!isOwner && !isLabourer) {
      return c.json({ msg: "Unauthorized to view this booking" }, 401);
    }

    return c.json(booking);

  } catch (err: any) {
    console.error(err.message);
    return c.json({ msg: "Server Error" }, 500);
  }
});

