// PUT /api/bookings/:id/status
bookings.put("/:id/status", verifyToken, async (c) => {
  const userId = c.get("user").id;
  const bookingId = c.req.param("id");
  const { status } = await c.req.json();

  const validStatuses = ["pending", "confirmed", "arrived", "completed", "cancelled"];
  if (!validStatuses.includes(status)) {
    return c.json({ msg: "Invalid status" }, 400);
  }

  try {
    const booking = await queryOne("SELECT * FROM bookings WHERE id = $1", [bookingId]);
    if (!booking) return c.json({ msg: "Booking not found" }, 404);

    const isUserOwner = booking.userId === userId;
    let isWorkerOwner = false;
    let workerLabourerId = null;

    if (booking.labourerId) {
      const labourer = await queryOne("SELECT id, user_id FROM labourers WHERE id = $1", [booking.labourerId]);
      if (labourer && labourer.userId === userId) {
        isWorkerOwner = true;
        workerLabourerId = labourer.id;
      }
    }

    if (!isUserOwner && !isWorkerOwner) {
      return c.json({ msg: "Not authorized" }, 401);
    }

    let arrivalOTP = booking.arrivalOtp;
    let completionOTP = booking.completionOtp;

    if (status === "confirmed" && (!arrivalOTP || !completionOTP)) {
      arrivalOTP = generateOTP();
      completionOTP = generateOTP();
    }

    const previousStatus = booking.status;

    // cancellation refund logic
    if (status === "cancelled" && previousStatus !== "cancelled") {
      if (booking.paymentStatus === "paid") {
        let refundAmount = Number(booking.commissionAmount || 0);
        if (refundAmount > 0) {
          if (previousStatus === "confirmed" || previousStatus === "arrived") {
            let refundPercentage = 50;
            const setting = await queryOne("SELECT value FROM settings WHERE key = 'cancellationRefundPercentage'");
            if (setting && setting.value !== undefined) {
              refundPercentage = Number(setting.value);
            }
            refundAmount = (refundAmount * refundPercentage) / 100;
          }

          if (refundAmount > 0) {
            const user = await queryOne("SELECT wallet_balance FROM users WHERE id = $1", [booking.userId]);
            const newBalance = Number(user?.walletBalance || 0) + refundAmount;
            await query("UPDATE users SET wallet_balance = $1 WHERE id = $2", [newBalance, booking.userId]);

            const txId = generateId();
            await query(
              `INSERT INTO wallet_transactions (id, user_id, amount, type, description, date, related_booking_id) 
               VALUES ($1, $2, $3, 'credit', $4, NOW(), $5)`,
              [txId, booking.userId, refundAmount, `Refund for cancelled booking: ${booking.category}`, bookingId]
            );
          }
        }
      }
    }

    await query(
      `UPDATE bookings 
       SET status = $1, arrival_otp = $2, completion_otp = $3 
       WHERE id = $4`,
      [status, arrivalOTP, completionOTP, bookingId]
    );

    const updatedBooking = await populateBooking(await queryOne("SELECT * FROM bookings WHERE id = $1", [bookingId]));

    // socket update
    await notifyBookingUpdate(bookingId, updatedBooking);

    // Notify Counterparty
    let targetUserId = null;
    if (isWorkerOwner) {
      targetUserId = booking.userId;
    } else if (isUserOwner && booking.labourerId) {
      const l = await queryOne("SELECT user_id FROM labourers WHERE id = $1", [booking.labourerId]);
      if (l) targetUserId = l.userId;
    }

    if (targetUserId) {
      const u = await queryOne("SELECT fcm_token FROM users WHERE id = $1", [targetUserId]);
      if (u && u.fcmToken) {
        await sendNotification(
          u.fcmToken,
          "Booking Update",
          `Your booking status has been updated to ${status.toUpperCase()}`,
          {
            type: "booking",
            bookingId,
            status
          }
        );
      }
    }

    return c.json(updatedBooking);

  } catch (err: any) {
    console.error(err.message);
    return c.json({ msg: "Server Error" }, 500);
  }
});

