       SET status = 'completed', is_work_confirmed = true, commission_amount = $1, worker_payout_amount = 0, payment_status = 'released' 
       WHERE id = $2`,
      [commissionAmount, bookingId]
    );

    // Increment worker jobsCompleted
    await query("UPDATE labourers SET jobs_completed = jobs_completed + 1 WHERE id = $1", [labourer.id]);

    const updatedBooking = await populateBooking(await queryOne("SELECT * FROM bookings WHERE id = $1", [bookingId]));

