  } catch (err: any) {
    console.error(err.message);
    return c.json({ msg: "Server Error" }, 500);
  }
});

// POST /api/bookings/:id/rate
bookings.post("/:id/rate", verifyToken, async (c) => {
  const userId = c.get("user").id;
  const bookingId = c.req.param("id");
  const { rating, comment } = await c.req.json();

  if (!rating || rating < 1 || rating > 5) {
    return c.json({ msg: "Please provide a valid rating between 1 and 5" }, 400);
  }

  try {
    const booking = await queryOne("SELECT * FROM bookings WHERE id = $1", [bookingId]);
    if (!booking) return c.json({ msg: "Booking not found" }, 404);

    if (booking.userId !== userId) {
      return c.json({ msg: "Not authorized" }, 401);
    }

    if (booking.status !== "completed") {
      return c.json({ msg: "Can only rate completed jobs" }, 400);
    }

    if (booking.isRated) {
      return c.json({ msg: "Already rated this booking" }, 400);
    }

    if (!booking.labourerId) {
      return c.json({ msg: "No worker assigned to rate" }, 400);
    }

    const user = await queryOne("SELECT name FROM users WHERE id = $1", [userId]);
    const reviewId = generateId();

    // Insert Review
    await query(
      `INSERT INTO reviews (id, labourer_id, user_id, user_name, rating, comment, date) 
       VALUES ($1, $2, $3, $4, $5, $6, NOW())`,
      [reviewId, booking.labourerId, userId, user?.name || "Customer", rating, comment || ""]
    );

    // Recalculate Labourer average rating
    const reviews = await query("SELECT rating FROM reviews WHERE labourer_id = $1", [booking.labourerId]);
    const total = reviews.reduce((acc: number, r: any) => acc + Number(r.rating), 0);
    const avgRating = total / reviews.length;

    await query("UPDATE labourers SET rating = $1 WHERE id = $2", [avgRating, booking.labourerId]);
    await query("UPDATE bookings SET is_rated = true WHERE id = $1", [bookingId]);

    const updatedBooking = await populateBooking(await queryOne("SELECT * FROM bookings WHERE id = $1", [bookingId]));
    return c.json({ msg: "Review submitted successfully!", booking: updatedBooking });

  } catch (err: any) {
    console.error(err.message);
    return c.json({ msg: "Server Error" }, 500);
  }
});

