import { Hono } from "https://deno.land/x/hono@v3.4.1/mod.ts";
import Razorpay from "npm:razorpay@^2.9.0";
import crypto from "node:crypto";
import { query, queryOne, generateId } from "./db.ts";
import { verifyToken } from "./auth.ts";
import { completePaymentLogic } from "./bookings.ts";

const payments = new Hono();

// Initialize Razorpay
let razorpay: any = null;
try {
  const keyId = Deno.env.get("RAZORPAY_KEY_ID");
  const keySecret = Deno.env.get("RAZORPAY_KEY_SECRET");
  if (keyId && keySecret) {
    razorpay = new Razorpay({ key_id: keyId, key_secret: keySecret });
  }
} catch (err: any) {
  console.warn("Failed to initialize Razorpay in payments:", err.message);
}

// POST /api/payments/create-order
payments.post("/create-order", verifyToken, async (c) => {
  const { bookingId } = await c.req.json();
  const userId = c.get("user").id;

  if (!razorpay) {
    return c.json({ msg: "Payment service configuration error." }, 500);
  }

  try {
    const booking = await queryOne("SELECT * FROM bookings WHERE id = $1", [bookingId]);
    if (!booking) return c.json({ msg: "Booking not found" }, 404);

    if (booking.paymentStatus === "paid") {
      return c.json({ msg: "Already paid", code: "ALREADY_PAID" }, 400);
    }

    let feeAmount = Number(booking.commissionAmount || 0);

    // Recalculate if 0 (legacy check)
    if (feeAmount === 0) {
      const categoryObj = await queryOne("SELECT commission_percentage, hourly_rate FROM categories WHERE name = $1", [booking.category]);
      if (categoryObj) {
        const commission = Number(categoryObj.commissionPercentage || 0);
        const referenceAmount = Number(booking.amount || booking.minAmount || 0);
        if (referenceAmount > 0) {
          feeAmount = Math.ceil((referenceAmount * commission) / 100);
        } else if (commission > 0) {
          feeAmount = Math.max(commission, 20);
        }
      }
    }

    if (feeAmount < 1) {
      return c.json({ msg: "Booking fee is 0. Please use confirm-free-booking route." }, 400);
    }

    const options = {
      amount: Math.round(feeAmount * 100), // paise
      currency: "INR",
      receipt: `receipt_booking_${bookingId}`,
      notes: { bookingId: bookingId, userId: userId }
    };

    const order = await razorpay.orders.create(options);
    await query("UPDATE bookings SET order_id = $1, commission_amount = $2 WHERE id = $3", [order.id, feeAmount, bookingId]);

    return c.json(order);

  } catch (err: any) {
    console.error("Razorpay Error:", err);
    return c.json({ msg: "Error creating order" }, 500);
  }
});

// POST /api/payments/verify-payment
payments.post("/verify-payment", verifyToken, async (c) => {
  const { razorpay_order_id, razorpay_payment_id, razorpay_signature, bookingId } = await c.req.json();

  const keySecret = Deno.env.get("RAZORPAY_KEY_SECRET") || "";
  const body = razorpay_order_id + "|" + razorpay_payment_id;
  const expectedSignature = crypto
    .createHmac("sha256", keySecret)
    .update(body)
    .digest("hex");

  if (expectedSignature === razorpay_signature) {
    try {
      await completePaymentLogic(bookingId, razorpay_payment_id);
      return c.json({ success: true, msg: "Payment verified successfully" });
    } catch (err: any) {
      console.error("Payment logic execution error:", err.message);
      return c.json({ success: false, msg: "Error processing payment logic" }, 500);
    }
  } else {
    return c.json({ success: false, msg: "Invalid signature" }, 400);
  }
});

