       VALUES ($1, $2, $3, 'debit', $4, NOW(), $5)`,
      [txId, userId, feeAmount, `Payment for Booking: ${booking.category}`, bookingId]
    );

    // Complete payment logic
    await completePaymentLogic(bookingId, "WALLET_PAYMENT");
    return c.json({ success: true, msg: "Payment completed successfully using wallet" });

  } catch (err: any) {
    console.error("Wallet Payment Error:", err.message);
    return c.json({ msg: "Error processing wallet payment" }, 500);
