// GET /api/settings/check-location
settings.get("/check-location", async (c) => {
  try {
    const lat = parseFloat(c.req.query("lat") || "");
    const lng = parseFloat(c.req.query("lng") || "");

    if (isNaN(lat) || isNaN(lng)) {
      return c.json({ msg: "Invalid coordinates. Provide lat and lng as query params." }, 400);
    }

    const zonesSetting = await queryOne("SELECT value FROM settings WHERE key = 'serviceZones'");
    let zones: any[] = [];

    if (zonesSetting && zonesSetting.value) {
      if (typeof zonesSetting.value === "string") {
        try {
          zones = JSON.parse(zonesSetting.value);
        } catch (_) {
          zones = [];
        }
      } else if (Array.isArray(zonesSetting.value)) {
        zones = zonesSetting.value;
      }
    }

    if (zones.length === 0) {
      const citiesSetting = await queryOne("SELECT value FROM settings WHERE key = 'enabledCities'");
      if (!citiesSetting || !citiesSetting.value || citiesSetting.value.toString().trim() === "") {
        return c.json({ active: true, nearestZone: null, method: "no_restrictions" });
      }
      return c.json({ active: null, nearestZone: null, method: "legacy_text_only" });
    }

    const result = isPointInAnyZone(lat, lng, zones);
    return c.json({ ...result, method: "geofence" });

  } catch (err: any) {
    console.error("Error in GET /settings/check-location:", err.message);
    return c.json({ msg: "Server Error", error: err.message }, 500);
  }
});

