import { Hono } from "https://deno.land/x/hono@v3.4.1/mod.ts";
import { query, queryOne, generateId } from "./db.ts";
import { verifyToken } from "./auth.ts";
import { sendNotification } from "./notifications.ts";

const chat = new Hono();

// Helper: Populate message sender
async function populateMessage(message: any): Promise<any> {
  if (!message) return null;
  const populated = { ...message };

  if (message.senderId) {
    const sender = await queryOne(
      `SELECT id, name, profile_picture as "profilePicture" FROM users WHERE id = $1`,
      [message.senderId]
    );
    populated.sender = sender || {};
    delete populated.senderId;
  }
  return populated;
}

// GET /api/chat/:bookingId
chat.get("/:bookingId", verifyToken, async (c) => {
  const bookingId = c.req.param("bookingId");
  try {
    const booking = await queryOne("SELECT id FROM bookings WHERE id = $1", [bookingId]);
    if (!booking) return c.json({ msg: "Booking not found" }, 404);

    const rawList = await query(
      "SELECT * FROM messages WHERE booking_id = $1 ORDER BY created_at ASC",
      [bookingId]
    );
    const populated = await Promise.all(rawList.map((m: any) => populateMessage(m)));
    return c.json(populated);
  } catch (err: any) {
    console.error(err.message);
    return c.json({ msg: "Server Error" }, 500);
  }
});

// POST /api/chat
chat.post("/", verifyToken, async (c) => {
  const userId = c.get("user").id;
  const { bookingId, text } = await c.req.json();

  if (!bookingId || !text) {
    return c.json({ msg: "Booking ID and text are required" }, 400);
  }

  try {
    const messageId = generateId();
    await query(
      `INSERT INTO messages (id, booking_id, sender_id, text, created_at) 
       VALUES ($1, $2, $3, $4, NOW())`,
      [messageId, bookingId, userId, text]
    );

    const message = await queryOne("SELECT * FROM messages WHERE id = $1", [messageId]);
    const populated = await populateMessage(message);

    // Socket update via Postgres NOTIFY
    try {
      const payload = JSON.stringify({ bookingId, event: "new_message", data: populated });
      await query("SELECT pg_notify('booking_updates', $1)", [payload]);
    } catch (sErr: any) {
      console.error("Socket notify error:", sErr.message);
    }

    // Push notification logic
    try {
      const booking = await queryOne("SELECT * FROM bookings WHERE id = $1", [bookingId]);
      if (booking) {
        let recipientId = null;
        if (userId === booking.userId) {
          // Customer sent it -> recipient is worker
          if (booking.labourerId) {
            const labourer = await queryOne("SELECT user_id FROM labourers WHERE id = $1", [booking.labourerId]);
            recipientId = labourer?.userId || null;
          }
        } else {
          // Worker sent it -> recipient is customer
          recipientId = booking.userId;
        }

        if (recipientId) {
          const recipient = await queryOne("SELECT fcm_token FROM users WHERE id = $1", [recipientId]);
          if (recipient && recipient.fcmToken) {
            await sendNotification(
              recipient.fcmToken,
              "New Message",
              text,
              {
                type: "chat",
                bookingId: bookingId,
                senderName: populated.sender?.name || "User"
              }
            );
          }
        }
      }
    } catch (nErr: any) {
      console.error("Failed to send chat notification:", nErr.message);
    }

    return c.json(populated);

  } catch (err: any) {
    console.error("Send message error:", err.message);
    return c.json({ msg: "Server Error" }, 500);
  }
});

