  try {
    const totalUsersResult = await queryOne("SELECT COUNT(*)::int as count FROM users WHERE role = 'user'");
    const totalWorkersResult = await queryOne("SELECT COUNT(*)::int as count FROM users WHERE role = 'worker'");
    const totalBookingsResult = await queryOne("SELECT COUNT(*)::int as count FROM bookings");
    const completedBookingsResult = await queryOne("SELECT COUNT(*)::int as count FROM bookings WHERE status = 'completed'");

    // Active users in last 30 days
    const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();
    const activeUsersResult = await queryOne(
      "SELECT COUNT(DISTINCT user_id)::int as count FROM bookings WHERE created_at >= $1",
      [thirtyDaysAgo]
    );

    // Revenue calculation
    const revenueResult = await queryOne(
      "SELECT SUM(amount)::numeric as total FROM bookings WHERE payment_status = 'paid'"
    );

    // Recent bookings (limit 5)
    const recentBookingsList = await query(
      `SELECT b.*, u.name as user_name 
       FROM bookings b 
       LEFT JOIN users u ON b.user_id = u.id 
       ORDER BY b.created_at DESC 
       LIMIT 5`
    );

    const recentBookings = recentBookingsList.map((b: any) => {
      const item = { ...b };
      if (b.userId) {
        item.user = { id: b.userId, name: b.userName };
      }
      delete item.userId;
      delete item.userName;
      return item;
    });

    return c.json({
      stats: {
        totalUsers: totalUsersResult?.count || 0,
        totalWorkers: totalWorkersResult?.count || 0,
        totalBookings: totalBookingsResult?.count || 0,
        completedBookings: completedBookingsResult?.count || 0,
        totalRevenue: Number(revenueResult?.total || 0),
        activeUsers: activeUsersResult?.count || 0
      },
      recentBookings
    });

