admin.put("/categories/:id", verifyToken, verifyAdmin, async (c) => {
  const id = c.req.param("id");
  const body = await c.req.json();

  try {
    // Generate update fields dynamically
    const allowedFields = [
      "name", "icon_name", "description", "supported_modes", "hourly_rate",
      "daily_rate", "task_rate", "min_hourly_rate", "max_hourly_rate", "commission_percentage", "is_active"
    ];

    const sets: string[] = [];
    const values: any[] = [];
    let counter = 1;

    for (const [key, value] of Object.entries(body)) {
      // convert camelCase keys to snake_case for setting
      const snakeKey = key.replace(/[A-Z]/g, letter => `_${letter.toLowerCase()}`);
      if (allowedFields.includes(snakeKey)) {
        sets.push(`${snakeKey} = $${counter}`);
        values.push(Array.isArray(value) ? value : value);
        counter++;
      }
    }

    if (sets.length === 0) {
      return c.json({ msg: "No valid update fields" }, 400);
    }

    values.push(id);
    const category = await queryOne(
      `UPDATE categories SET ${sets.join(', ')}, created_at = created_at WHERE id = $${counter} RETURNING *`,
      values
    );

    return c.json(category);

  } catch (err: any) {
    console.error(err.message);
    return c.json({ msg: "Server Error" }, 500);
  }
});

