// GET /api/admin/bookings
admin.get("/bookings", verifyToken, verifyAdmin, async (c) => {
  try {
    const bookingsList = await query(
      `SELECT b.*, u.name as user_name, u.email as user_email, l.name as worker_name 
       FROM bookings b 
       LEFT JOIN users u ON b.user_id = u.id 
       LEFT JOIN labourers l ON b.labourer_id = l.id 
       ORDER BY b.created_at DESC`
    );

    const formatted = bookingsList.map((b: any) => {
      const item = { ...b };
      if (b.userId) {
        item.user = { id: b.userId, name: b.userName, email: b.userEmail };
      }
      if (b.labourerId) {
        item.labourer = { id: b.labourerId, name: b.workerName };
      }
      delete item.userId;
      delete item.userName;
      delete item.userEmail;
      delete item.labourerId;
      delete item.workerName;
      return item;
    });

    return c.json(formatted);

  } catch (err: any) {
    console.error(err.message);
    return c.json({ msg: "Server Error" }, 500);
  }
});

