// PUT /api/admin/help-requests/:id
admin.put("/help-requests/:id", verifyToken, verifyAdmin, async (c) => {
  const id = c.req.param("id");
  const { status } = await c.req.json();

  if (!["pending", "in-progress", "resolved"].includes(status)) {
    return c.json({ msg: "Invalid status value" }, 400);
  }

  try {
    const helpRequest = await queryOne(
      "UPDATE help_requests SET status = $1 WHERE id = $2 RETURNING *",
      [status, id]
    );
    if (!helpRequest) {
      return c.json({ msg: "Help request not found" }, 404);
    }
    return c.json(helpRequest);
  } catch (err: any) {
    console.error(err.message);
    return c.json({ msg: "Server Error" }, 500);
  }
});

