import admin from "npm:firebase-admin@^13.6.0";
import { query } from "./db.ts";

let isFirebaseInitialized = false;

function initFirebase() {
  if (isFirebaseInitialized) return true;

  if (admin.apps.length > 0) {
    isFirebaseInitialized = true;
    return true;
  }

  const serviceAccountVar = Deno.env.get("FIREBASE_SERVICE_ACCOUNT");
  if (serviceAccountVar) {
    try {
      const serviceAccount = JSON.parse(serviceAccountVar);
      admin.initializeApp({
        credential: admin.credential.cert(serviceAccount)
      });
      isFirebaseInitialized = true;
      console.log("Firebase Admin Initialized successfully.");
      return true;
    } catch (error: any) {
      console.warn("WARNING: Firebase Admin failed to initialize:", error.message);
    }
  } else {
    console.warn("WARNING: FIREBASE_SERVICE_ACCOUNT env var not found. Notifications will be skipped.");
  }
  return false;
}

export async function sendNotification(
  fcmToken: string,
  title: string,
  body: string,
  data: Record<string, string> = {}
): Promise<void> {
  if (!initFirebase()) return;
  if (!fcmToken) {
    console.warn("[Notification] Skipping: No FCM Token provided.");
    return;
  }

  console.log(`[Notification] Sending to token starting with: ${fcmToken.substring(0, 10)}...`);
  try {
    const response = await admin.messaging().send({
      token: fcmToken,
      notification: { title, body },
      data
    });
    console.log(`[Notification] Successfully sent: ${response}`);
  } catch (error: any) {
    console.error(`[Notification] Error sending message:`, error.message);

    // Check if token is invalid or expired, if so, remove it from the user profiles
    const errCode = error.code || "";
    if (
      errCode === 'messaging/registration-token-not-registered' || 
      errCode === 'messaging/invalid-registration-token'
    ) {
      console.warn(`[Notification] Token is invalid, removing from database: ${fcmToken.substring(0, 10)}...`);
      try {
        await query("UPDATE users SET fcm_token = '' WHERE fcm_token = $1", [fcmToken]);
        console.log(`[Notification] Invalid token cleared from database.`);
      } catch (dbErr: any) {
        console.error(`[Notification] Failed to clear invalid token:`, dbErr.message);
      }
    }
  }
}

export async function sendBroadcastNotification(
  tokens: string[],
  title: string,
  body: string,
  data: Record<string, string> = {}
): Promise<void> {
  if (!initFirebase()) return;
  if (!tokens || tokens.length === 0) {
    console.warn("[Notification] Skipping broadcast: No tokens provided.");
    return;
  }

  console.log(`[Notification] Broadcasting to ${tokens.length} tokens.`);
  try {
    const response = await admin.messaging().sendEachForMulticast({
      tokens,
      notification: { title, body },
      data
    });
    console.log(`[Notification] Multicast results: ${response.successCount} successes, ${response.failureCount} failures.`);

    if (response.failureCount > 0) {
      const invalidTokens: string[] = [];
      response.responses.forEach((resp, idx) => {
        if (!resp.success) {
          const errCode = resp.error?.code || "";
          if (
            errCode === 'messaging/registration-token-not-registered' || 
            errCode === 'messaging/invalid-registration-token'
          ) {
            invalidTokens.push(tokens[idx]);
          }
        }
      });

      if (invalidTokens.length > 0) {
        console.warn(`[Notification] Clearing ${invalidTokens.length} invalid tokens...`);
        try {
          await query("UPDATE users SET fcm_token = '' WHERE fcm_token = ANY($1)", [invalidTokens]);
          console.log(`[Notification] Cleaned up invalid multicast tokens.`);
        } catch (dbErr: any) {
          console.error(`[Notification] Failed to cleanup invalid multicast tokens:`, dbErr.message);
        }
      }
    }
  } catch (error: any) {
    console.error("[Notification] Error in multicast broadcast:", error.message);
  }
}

import { Hono } from "https://deno.land/x/hono@v3.4.1/mod.ts";
import { query, queryOne, generateId } from "./db.ts";
import { verifyToken } from "./auth.ts";

const labourers = new Hono();

